import React, { useState } from 'react';

// Create the Counter component here
const Counter = () => {
  // Initialize count state here
  const [count, setCount] = useState<number>(0);

  // Define increment handler function here
  const handleIncrement = () => {
    setCount(count + 1);
  };

  // Define decrement handler function here
  const handleDecrement = () => {
    setCount(count - 1);
  };

  // Define reset handler function here
  const handleReset = () => {
    setCount(0);
  };

  return (
    <div>
      {/* Add paragraph displaying count here */}
      <p>Current count: {count}</p>
      {/* Add increment button with click handler here */}
      <button onClick={handleIncrement}>Increment</button>
      {/* Add decrement and reset buttons with handlers here */}
    </div>
  );
};
